def sig(dark=False, folio=""):
    c = "#FA581A" if dark else "#D9480F"
    right = f'<div class="folio">{folio}</div>' if folio else f'<div class="brand">{RAIO.format(c=c)}Ignit Agency</div>'
    return (f'<div class="sig"><div class="who"><div class="name">Cristiano Pereira</div>'
            f'<div class="role">Growth &amp; Performance · Mídia paga</div></div>{right}</div>')


import pathlib
CSS = (pathlib.Path(__file__).resolve().parent / 'base.css').as_uri()


def page(body, css_extra="", cls="frame"):
    return (f'<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">'
            f'<link rel="stylesheet" href="{CSS}"><style>{css_extra}</style></head>'
            f'<body><div class="{cls}">{body}</div></body></html>')
